package ai.novita.sandbox.core;
import java.time.Instant;
public class EntryInfo { private String name,path,permissions,owner,group,symlinkTarget; private boolean isDir; private long size; private int mode; private Instant modifiedTime; public String getName(){return name;} public String getPath(){return path;} public boolean isDir(){return isDir;} public boolean isFile(){return !isDir;} public long getSize(){return size;} public int getMode(){return mode;} public String getPermissions(){return permissions;} public String getOwner(){return owner;} public String getGroup(){return group;} public Instant getModifiedTime(){return modifiedTime;} public String getSymlinkTarget(){return symlinkTarget;} public void setName(String v){name=v;} public void setPath(String v){path=v;} public void setDir(boolean v){isDir=v;} public void setSize(long v){size=v;} public void setMode(int v){mode=v;} public void setPermissions(String v){permissions=v;} public void setOwner(String v){owner=v;} public void setGroup(String v){group=v;} public void setModifiedTime(Instant v){modifiedTime=v;} public void setSymlinkTarget(String v){symlinkTarget=v;} }
